INSERT INTO site_settings ("id", "name", "initials", "role", "tagline", "intro", "location", "email", "linkedin", "cv_url", "created_date", "updated_date") VALUES ('6af19d7ebb3afd2716dc9380', 'Anthony Gouvrillon', 'AG', 'Chef de projet IT', 'Faire avancer les projets. Donner du sens à la technologie.', 'Chef de projet IT depuis plus de 20 ans (jeu vidéo, GED/OCR, ingénierie événementielle), je pilote les projets du cadrage au déploiement avec une bonne facilité de compréhension technique et fonctionnelle des sujets.', 'Nantes', 'antogouvrillon@gmail.com', 'https://linkedin.com/in/anthonygouvrillon', '', '2026-11-09T10:16:30.213000', '2026-11-09T12:10:20.581000');
